python3 - <<'PY'
p='src/types/checker/inference/objects/methods.rs'
s=open(p).read()
count = 0
for marker in ["                        sig.params[i].1 =\n                            Self::specialize_generic_array_param_hint(&sig.params[i].1, arg_ty);\n"]:
    while marker in s:
        s = s.replace(marker,
"""                        // A BY-REFERENCE parameter never adopts the call site's element type:
                        // the callee writes into the CALLER's storage, and a body compiled for
                        // `array<int>` that widens mid-call rewrites that storage to boxed slots
                        // while the caller still reads raw ones. `$o->go($ints)` printed
                        // ADDRESSES for exactly that reason.
                        let by_ref = sig.ref_params.get(i).copied().unwrap_or(false);
                        let current = sig.params[i].1.clone();
                        sig.params[i].1 = if by_ref {
                            Self::by_ref_array_param_type(&current, arg_ty)
                                .unwrap_or(current)
                        } else {
                            Self::specialize_generic_array_param_hint(&current, arg_ty)
                        };
""", 1)
        count += 1
open(p,'w').write(s)
print('patched', count, 'method specialization sites')
